Method.Implementation:
    $$$TRACE("call web service " _ pRequest.ClinFileNm _", " _ pRequest.InXDRTouchWorksPnRFileNm _ " with new Msg Id: " _ $EXTRACT(pRequest.clinID, 1, 12))
    set pResponse = ##class(Ens.StringResponse).%New()
    set pResponse.StringValue = "Curl to send data to WebService"

    set curlDataFileNm = pRequest.workPath _ "newDataFile-" _ pRequest.clinID 
    // MAINXMLDATA CLINDATA HREFNUM MSGID OutFileName

    set stat = ##class(IHC.ITF.ITFCOMMON.Utility).ExecuteShellCmd(..CreateFileScript _ " " _ pRequest.InXDRTouchWorksPnRFileNm _ " " _ ..CurlDataTemplate _ " " _ pRequest.ClinFileNm _ " " _ pRequest.clinID _ " " _ $EXTRACT(pRequest.clinID, 1, 12) _ " " _ curlDataFileNm, pRequest.workPath _ "CreateDataFileOut-"_ pRequest.clinID, pRequest.workPath _ "CreateDataFileErr-"_ pRequest.clinID)
    If ##class(%File).Exists(curlDataFileNm)
    {
	    $$$TRACE(..CreateFileScript _ " Script created data file: " _ curlDataFileNm)
	    set curlStdOutFile = pRequest.workPath _ "curlOut-"_ pRequest.clinID 
	    set curlStdErrFile = pRequest.workPath _"curlErr-"_ pRequest.clinID
        set stat = ##class(IHC.ITF.ITFCOMMON.Utility).ExecuteShellCmd(..CurlSendScript _ " " _ curlDataFileNm, curlStdOutFile, curlStdErrFile)
        $$$TRACE(..CurlSendScript _ " Stat: " _ stat)

        if (stat = 0)
        {
        	set pResponse.StringValue = "WebService response: "
        	if (..CheckForReturnStatus(curlStdErrFile, "HTTP/2 200", pResponse) = $$$OK)
        	{

        		if (..CheckForReturnStatus(curlStdOutFile, "ResponseStatusType:Success", pResponse) = $$$OK)
        		{

	        		set stat = $$$OK
        		}
        		else
        		{

	        		set stat = $$$ERROR($$$GeneralError, "Invalid Response from Curl: " _ pResponse.StringValue)
        		}
        	}
        	else
        	{

	        	set stat = $$$ERROR($$$GeneralError, "Invalid Response from Curl: " _ pResponse.StringValue)
        	}

        }
        else
        {
	        set pResponse.StringValue = ..CurlSendScript _ " Stat: " _ stat
	       	set stat = $$$ERROR($$$GeneralError, "Invalid Response from Curl: " _ ..CurlSendScript _ " Stat: " _ stat)
        }
    }
    else
    {
	    set stat = $$$ERROR($$$GeneralError, ..CreateFileScript _ " could not create MTOM Data file: " _ curlDataFileNm _", error: " _ stat)
    }

 QUIT stat

	set stat = $$$ERROR($$$GeneralError, "Check Response Failure ")
	$$$TRACE("CheckForReturnStatus: " _ searchStr _ ", " _ pFileName)
	if ( '##class(%File).Exists(pFileName))
	{
		set pResponse.StringValue = pResponse.StringValue _ " Command did not create the file: " _ pFileName
		QUIT stat
	} 

    Set tFile = ##class(%File).%New(pFileName)
	if ( tFile.Size <= 0)
	{
		set pResponse.StringValue =pResponse.StringValue _ " Command did not generate any response in the file: " _ pFileName
		QUIT stat
	}

	Do tFile.Open("R")

	Do tFile.Rewind()


	While ('tFile.AtEnd) {
			Set tLine = tFile.ReadLine()
			// $$$TRACE("Search file: " _ tLine _ "::: " _ searchStr)
			if (tLine [ searchStr)
			{
				set stat = $$$OK
				set pResponse.StringValue =pResponse.StringValue _ " Found the line: " _ tLine
				// $$$TRACE(" Found the Response: " _ tLine)
				QUIT
			}
	}
	Do tFile.Close()
	if $$$ISERR(stat)
	{
		set pResponse.StringValue = pResponse.StringValue _ searchStr _ " not found in " _ pFileName
	}
	return stat
